  --accent-hover:   #2ea043;
  --accent-text:    #ffffff;
  --error-text:     #f85149;
  --help-text:      #8b949e;
  --required:       #f78166;
  --success-bg:     #0d2818;
  --success-border: #238636;
  --success-text:   #56d364;
  --radius:         6px;
  --transition:     0.15s ease;
}

/* ── Accessibility helpers ────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--border-focus);
  color: var(--bg-page);
  font-weight: 700;
  border-radius: var(--radius);
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0.75rem; }

/* ── Base typography ──────────────────────────────────────────────── */
html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Layout ───────────────────────────────────────────────────────── */
.container {
  width: 100%;
  max-width: 560px;
  margin-inline: auto;
  padding-inline: 1.25rem;
}

/* ── Header ───────────────────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 0;
  background: var(--bg-card);
}

.site-logo {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  letter-spacing: 0.02em;
}

/* ── Card ─────────────────────────────────────────────────────────── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem 2rem 2.5rem;
  margin-block: 2.5rem;
}

.form-card h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
  color: var(--text-primary);
}

.form-subtitle {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 1.75rem;
}

/* ── Live regions ─────────────────────────────────────────────────── */
#form-status,
#form-alert {
  /* Hidden until populated */
  display: none;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  margin-bottom: 1.25rem;
  font-size: 0.9rem;
}

#form-status.visible {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  color: var(--success-text);
}

#form-alert.visible {
  display: block;
  background: #2d1418;
  border: 1px solid var(--border-error);
  color: var(--error-text);
}

/* ── Required note ────────────────────────────────────────────────── */
.required-note {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

/* ── Form fields ──────────────────────────────────────────────────── */
.form-field {
  margin-bottom: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-label);
}

.required-marker {
  color: var(--required);
  margin-left: 0.1em;
}

.optional-marker {
  font-weight: 400;
  color: var(--text-secondary);
  font-size: 0.8em;
  margin-left: 0.25em;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.55rem 0.75rem;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}

input[type="text"]:hover,
input[type="email"]:hover,
input[type="tel"]:hover {
  border-color: #58616d;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.2);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(248, 81, 73, 0.25);
}

/* ── Help & error text ────────────────────────────────────────────── */
.field-help {
  font-size: 0.8rem;
  color: var(--help-text);
}

.field-error {
  font-size: 0.8rem;
  color: var(--error-text);
}

/* Hidden until triggered by JS */
.field-error[aria-hidden="true"] {
  display: none;
}

/* ── Submit button ────────────────────────────────────────────────── */
.submit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 0.5rem;
  padding: 0.6rem 1.5rem;
  background: var(--accent);
  color: var(--accent-text);
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-size: 0.95rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
}

.submit-btn:hover { background: var(--accent-hover); }

.submit-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.4);
}

/* ── Forced Colors (Windows High Contrast) ────────────────────────── */
@media (forced-colors: active) {
  input, .submit-btn { forced-color-adjust: auto; }
  .field-error       { color: LinkText; }
  .required-marker   { color: Mark; }
}

/* ── Reduced motion ───────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
