 (() => {
   const form        = document.getElementById('contact-form');
   const statusEl    = document.getElementById('form-status');
   const alertEl     = document.getElementById('form-alert');

   // ── Field descriptors ────────────────────────────────────────────
   const fields = [
     {
       id:       'full-name',
       errorId:  'full-name-error',
       label:    'Full name',
       required: true,
       validate(value) {
         if (!value.trim()) return 'Error: Full name is required.';
         return null;
       },
     },
     {
       id:       'email',
       errorId:  'email-error',
       label:    'Email address',
       required: true,
       validate(value) {
         if (!value.trim()) return 'Error: Email address is required.';
         // Basic RFC-like check — browsers cover the rest via type="email"
         if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
           return 'Error: Enter a valid email address, e.g. name@example.com.';
         }
         return null;
       },
     },
   ];

   // ── Helpers ──────────────────────────────────────────────────────

   function showError(field, message) {
     const input = document.getElementById(field.id);
     const errorEl = document.getElementById(field.errorId);

     input.setAttribute('aria-invalid', 'true');
     errorEl.textContent = message;
     errorEl.setAttribute('aria-hidden', 'false');
   }

   function clearError(field) {
     const input = document.getElementById(field.id);
     const errorEl = document.getElementById(field.errorId);

     input.removeAttribute('aria-invalid');
     errorEl.textContent = '';
     errorEl.setAttribute('aria-hidden', 'true');
   }

   function clearStatus() {
     statusEl.textContent = '';
     statusEl.classList.remove('visible');
     alertEl.textContent = '';
     alertEl.classList.remove('visible');
   }

   // ── Live validation after first submit attempt ───────────────────
   function attachLiveValidation() {
     fields.forEach((field) => {
       const input = document.getElementById(field.id);
       input.addEventListener('input', () => {
         const error = field.validate(input.value);
         if (error) {
           showError(field, error);
         } else {
           clearError(field);
         }
       });
     });
   }

   let liveValidationAttached = false;

   // ── Submit handler ───────────────────────────────────────────────
   form.addEventListener('submit', (event) => {
     event.preventDefault();
     clearStatus();

     const errors = [];

     fields.forEach((field) => {
       const input = document.getElementById(field.id);
       const error = field.validate(input.value);
       if (error) {
         showError(field, error);
         errors.push({ field, message: error });
       } else {
         clearError(field);
       }
     });

     // Attach live validation on first submit attempt
     if (!liveValidationAttached) {
       attachLiveValidation();
       liveValidationAttached = true;
     }

     if (errors.length > 0) {
       // Announce error count, then focus first invalid field
       const summary =
         errors.length === 1
           ? 'There is 1 error in this form. Please correct it before continuing.'
           : `There are ${errors.length} errors in this form. Please correct them before continuing.`;

       // Use role="alert" region for the summary (focus moves to first field separately)
       alertEl.textContent = summary;
       alertEl.classList.add('visible');

       // Move focus to first invalid field
       document.getElementById(errors[0].field.id).focus();
       return;
     }

     // ── Success ──────────────────────────────────────────────────
     // Reset form and notify via polite status region
     form.reset();
     fields.forEach(clearError);

     statusEl.innerHTML =
       '<span aria-hidden="true">✓</span> Message sent! We\'ll get back to you shortly.';
     statusEl.classList.add('visible');
   });
 })();

